--
-- Table structure for table `guests`
--

CREATE TABLE `guests` (
  `id` smallint(5) UNSIGNED NOT NULL COMMENT 'Unique identifier',
  `person_id` smallint(4) UNSIGNED DEFAULT NULL COMMENT 'Person ID',
  `show_id` tinyint(2) UNSIGNED DEFAULT NULL COMMENT 'Show ID',
  `season_id` smallint(3) UNSIGNED DEFAULT NULL COMMENT 'Season ID',
  `episode_id` smallint(4) UNSIGNED DEFAULT NULL COMMENT 'Episode ID',
  `sort_order` tinyint(2) UNSIGNED DEFAULT NULL COMMENT 'Manual sort order.',
  `notes` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Notes on guest appearance.'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

